package com.example.starter.salinity.po;

/**
 * 航次状态。
 *
 * <ul>
 *     <li>{@link #OPEN}：采样中，可提交样本、进行质控采纳；</li>
 *     <li>{@link #SEALED}：已封存，剖面已固化，禁止替换采纳版本，仅可追加勘误。</li>
 * </ul>
 */
public enum VoyageStatus {

    /** 采样中（可封存，封存失败不会离开该状态）。 */
    OPEN,

    /** 已封存（剖面冻结，不可再次封存）。 */
    SEALED
}

package com.example.starter.salinity.po;

import java.time.Instant;

/**
 * 航次持久化对象。
 *
 * @param id          自增主键
 * @param voyageCode  航次编号，业务唯一，非空
 * @param status      航次状态，非空；采样中为 {@link VoyageStatus#OPEN}，封存后为 {@link VoyageStatus#SEALED}
 * @param sealedUtc   封存 UTC 时刻；未封存时为 {@code null}
 * @param createdUtc  创建 UTC 时刻，非空
 */
public record Voyage(
        Long id,
        String voyageCode,
        VoyageStatus status,
        Instant sealedUtc,
        Instant createdUtc
) {
}

package com.example.starter.salinity.po;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 已冻结剖面的一个深度点，封存时刻快照写入，此后不再变化。
 *
 * @param id           自增主键
 * @param voyageCode   航次编号，非空
 * @param stationCode  站位编号，非空
 * @param depthM       深度，单位米；封存固化标准层 0、50、100
 * @param sampleId     被固化的采纳样本主键，非空
 * @param salinityPsu  固化时的盐度，单位 PSU
 * @param collectedUtc 样本采集 UTC 时刻
 * @param sealedUtc    本航次封存 UTC 时刻，非空
 */
public record SealedProfilePoint(
        Long id,
        String voyageCode,
        String stationCode,
        Integer depthM,
        Long sampleId,
        BigDecimal salinityPsu,
        Instant collectedUtc,
        Instant sealedUtc
) {
}

package com.example.starter.salinity.po;

import java.time.Instant;

/**
 * 封存后追加的勘误说明，仅追加不修改；原冻结剖面继续可查。
 *
 * @param id            自增主键
 * @param voyageCode    航次编号，非空
 * @param note          勘误正文，非空
 * @param refSealedUtc  所引用的原封存 UTC 时刻，非空
 * @param createdUtc    勘误创建 UTC 时刻，非空
 */
public record ProfileErratum(
        Long id,
        String voyageCode,
        String note,
        Instant refSealedUtc,
        Instant createdUtc
) {
}

package com.example.starter.salinity.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间来源配置；测试可替换为固定或可控时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 业务时间统一使用 UTC 系统时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.salinity.exception;

/**
 * 业务规则不可处理异常，映射 HTTP 422：越界采样、跨航次质控、封存缺深度等。
 */
public class BusinessRuleException extends RuntimeException {

    /**
     * @param message 面向调用方的错误说明
     */
    public BusinessRuleException(String message) {
        super(message);
    }
}

package com.example.starter.salinity.exception;

/**
 * 状态冲突异常，映射 HTTP 409：采样编号重复但内容不同、封存后替换采纳版本、重复封存等。
 */
public class ConflictException extends RuntimeException {

    /**
     * @param message 面向调用方的错误说明
     */
    public ConflictException(String message) {
        super(message);
    }
}

package com.example.starter.salinity.exception;

/**
 * 资源不存在异常，映射 HTTP 404。
 */
public class ResourceNotFoundException extends RuntimeException {

    /**
     * @param message 面向调用方的错误说明
     */
    public ResourceNotFoundException(String message) {
        super(message);
    }
}

