package com.example.starter.salinity.repo;

import java.util.List;
import java.util.Optional;

import com.example.starter.salinity.po.ProfileErratum;
import com.example.starter.salinity.po.SalinitySample;
import com.example.starter.salinity.po.SealedProfilePoint;
import com.example.starter.salinity.po.Voyage;

/**
 * 盐度采样持久化端口。
 */
public interface SalinityRepository {

    /** 不存在则注册航次（OPEN）；已存在不做改动。 */
    void registerVoyageIfAbsent(String voyageCode);

    /** 按编号查航次，不存在返回空。 */
    Optional<Voyage> findVoyage(String voyageCode);

    /** 插入一条原始样本，返回带主键的样本；采样编号/请求 ID 唯一冲突时抛出底层异常。 */
    SalinitySample insertSample(SalinitySample sample);

    /** 按采样编号查样本。 */
    Optional<SalinitySample> findSampleByNo(String sampleNo);

    /** 按请求 ID 查样本（幂等重放）。 */
    Optional<SalinitySample> findSampleByRequestId(String requestId);

    /** 查航次下全部样本，按主键升序（即入库先后）。 */
    List<SalinitySample> findSamples(String voyageCode);

    /**
     * 以行锁锁定航次行并返回；不存在返回空。封存事务内首先调用。
     */
    Optional<Voyage> lockVoyage(String voyageCode);

    /** 将航次标记为 SEALED 并记录封存时刻。 */
    void markSealed(String voyageCode, java.time.Instant sealedUtc);

    /**
     * 质控采纳：同一事务内把站位深度旧采纳版本置为非采纳并互相登记替换关系，再将目标样本置为采纳。
     *
     * @return 受影响行数；目标样本不存在或已不属该航次时为 0
     */
    int adoptWithinPosition(String voyageCode, String stationCode, int depthM,
                            Long targetId, Long oldAdoptedId);

    /** 查站位深度当前采纳样本。 */
    Optional<SalinitySample> findAdopted(String voyageCode, String stationCode, int depthM);

    /**
     * 封存一致性快照：对本航次全部站位深度加锁，并取各站位深度当前采纳版本。
     * 与 {@link #adoptWithinPosition} 的更新行锁互斥，保证封存拿到的是同一份一致版本集合。
     */
    List<SalinitySample> lockAndLoadAdoptedSnapshot(String voyageCode);

    /** 批量写入冻结剖面点（同一事务）。 */
    void insertProfilePoints(List<SealedProfilePoint> points);

    /** 查冻结剖面点，按站位、深度升序。 */
    List<SealedProfilePoint> findProfilePoints(String voyageCode);

    /** 追加勘误，返回带主键的记录。 */
    ProfileErratum insertErratum(ProfileErratum erratum);

    /** 查航次全部勘误，按主键升序。 */
    List<ProfileErratum> findErrata(String voyageCode);
}

package com.example.starter.salinity.service;

import com.example.starter.salinity.command.AddErratumCommand;
import com.example.starter.salinity.command.AdoptSampleCommand;
import com.example.starter.salinity.command.SealVoyageCommand;
import com.example.starter.salinity.command.SubmitSampleCommand;
import com.example.starter.salinity.view.SampleView;
import com.example.starter.salinity.view.VoyageDataView;

/**
 * 盐度采样业务服务：采样提交、质控替换、航次封存、勘误与查询。
 */
public interface SalinityService {

    /** 提交样本（同参重放返回原样本）。 */
    SampleView submit(SubmitSampleCommand command);

    /** 质控采纳指定样本为站位深度唯一版本。 */
    SampleView adopt(AdoptSampleCommand command);

    /** 封存航次，固化各站位 0、50、100 米剖面；失败不锁定航次。 */
    void seal(SealVoyageCommand command);

    /** 封存后追加勘误。 */
    void addErratum(AddErratumCommand command);

    /** 查询航次全部数据：原始样本、采纳版本、冻结剖面、勘误。 */
    VoyageDataView query(String voyageCode);
}

