    /** 插入一条原始样本，返回带主键的样本；采样编号/请求 ID 唯一冲突时抛出底层异常。 */
    SalinitySample insertSample(SalinitySample sample);

    /** 按采样编号查样本。 */
    Optional<SalinitySample> findSampleByNo(String sampleNo);

