     * 以行锁锁定航次行并返回；不存在返回空。采纳与封存事务内首先调用，统一加锁顺序。
     */
    Optional<Voyage> lockVoyage(String voyageCode);

    /** 将航次标记为 SEALED 并记录封存时刻。 */
    void markSealed(String voyageCode, Instant sealedUtc);

    /**
     * 锁定某站位深度的全部样本行（含当前采纳行），返回这些行；与封存快照的行锁互斥。
