                .orElseThrow(() -> new ResourceNotFoundException("航次不存在: " + command.voyageCode()));
        if (voyage.status() != VoyageStatus.SEALED || voyage.sealedUtc() == null) {
            throw new BusinessRuleException("航次未封存，不能追加勘误: " + command.voyageCode());
