        List<SalinitySample> adoptedSnapshot = repository.lockAndLoadAdoptedSnapshot(voyage.voyageCode());
        List<SalinitySample> allSamples = repository.findSamples(voyage.voyageCode());

        Set<String> stations = allSamples.stream()
