        Map<String, Map<Integer, SalinitySample>> adoptedByStationDepth = new LinkedHashMap<>();
        for (SalinitySample sample : adoptedSnapshot) {
            adoptedByStationDepth
                    .computeIfAbsent(sample.stationCode(), key -> new LinkedHashMap<>())
