                .satisfies(s -> assertThat(s.adopted()).isFalse());
    }

    private Thread.State findTaskThreadState(ExecutorService pool, String ignored) {
        Thread target = null;
        long youngest = Long.MAX_VALUE;
        for (Thread thread : Thread.getAllStackTraces().keySet()) {
            if (thread.getName().startsWith("pool-") && thread.getThreadGroup() == Thread.currentThread().getThreadGroup()
                    && thread.getId() < youngest
                    && thread.getState() != Thread.State.NEW) {
